runner:
async () => {
  // The §4 runner of .claude/skills/gpu-check/SKILL.md (click every tab, wait, read
  // `N/M passed`, the ✕ failed and the ⏳ pending names), extended like the Chrome runs
  // of M2/M3/M6: status, name and detail of every check, the HUD header, 7 s on the slow
  // tabs. Safari runs rAF at 60 Hz (Chrome at 120 on this display), so a check that
  // counts frames takes twice Chrome's wall time: after the fixed wait the runner keeps
  // polling every 500 ms while a check is still ⏳ (not on Input, whose 4 ⏳ wait for
  // real input), up to MAX_MS per tab.
  const ONLY = window.__m12Only ?? [];
  const MAX_MS = 15000;
  const SLOW = ['Lighting', 'Rendering FX', 'Lifecycle', '2D Twins'];
  const wait = (ms) => new Promise((r) => setTimeout(r, ms));
  const read = () => {
    const leaves = [...document.querySelectorAll('*')].filter((n) => n.children.length === 0);
    const summary = leaves.map((n) => n.textContent.trim()).filter((t) => /\d+\/\d+ passed/.test(t)).at(-1) ?? null;
    const failed = leaves.filter((n) => /^✕/.test(n.textContent.trim())).map((n) => n.parentElement.textContent.trim().slice(0, 100));
    const pending = leaves.filter((n) => /^⏳/.test(n.textContent.trim())).map((n) => n.parentElement.textContent.trim().slice(0, 60));
    const checks = [];
    for (const item of document.querySelectorAll('#check-list .check-item')) {
      const icon = item.querySelector('.check-icon');
      const status = ['pass', 'fail', 'skip', 'pending'].find((s) => icon && icon.classList.contains(s)) ?? (icon ? icon.textContent : '?');
      const name = item.querySelector('.check-name')?.textContent ?? '';
      const next = item.nextElementSibling;
      const detail = next && next.classList.contains('check-detail') ? next.textContent : '';
      checks.push({ status, name, detail });
    }
    const header = (document.getElementById('overlay')?.textContent ?? '').split('\n').at(-1);
    return { header, summary, failed, pending, checks };
  };
  const out = { mode: window.__hyperion?.mode ?? null, url: location.href, timeOrigin: performance.timeOrigin, startedAt: new Date().toISOString() };
  for (const tab of [...document.querySelectorAll('.tab')]) {
    const name = tab.textContent.trim();
    if (ONLY.length && !ONLY.includes(name)) continue;
    const t0 = performance.now();
    tab.click();
    await wait(SLOW.includes(name) ? 7000 : 3500);
    let r = read();
    while (name !== 'Input' && r.pending.length > 0 && performance.now() - t0 < MAX_MS) {
      await wait(500);
      r = read();
    }
    out[name] = { ...r, waitedMs: Math.round(performance.now() - t0), visibility: document.visibilityState };
  }
  out.endedAt = new Date().toISOString();
  out.timeOriginAtEnd = performance.timeOrigin;
  out.viteWsCloses = window.__viteWsCloses ?? null;
  out.visChanges = window.__visChanges ?? null;
  out.cap = window.__cap ?? null;
  return out;
}

guard:
async () => {
  // M12 post-navigation guard (Safari has no initScript under WebDriver; the BiDi
  // preload of safaridriver 27.0.1 runs nothing). Run right after each navigation.
  // (1) console capture into window.__cap: misses everything logged before it runs.
  // (2) anti-reload: Vite 6.4 reloads after `waitForSuccessfulPing`, which opens
  //     `new WebSocket(url, 'vite-ping')` through the global; a vite-ping socket that
  //     never opens keeps the page (recorded in window.__viteWsCloses). Touches
  //     neither the adapter nor the engine.
  if (!window.__cap) {
    window.__cap = [];
    window.__capFrom = 'post-navigation';
    window.__capInstalledAt = Math.round(performance.now());
    window.__capHyperionAtInstall = !!window.__hyperion;
    const fmt = (a) => {
      try {
        if (typeof a === 'string') return a;
        if (a instanceof Error) return String(a.stack || a);
        return JSON.stringify(a);
      } catch { return String(a); }
    };
    for (const level of ['error', 'warn', 'info', 'log']) {
      const orig = console[level];
      console[level] = function (...args) {
        try { window.__cap.push({ t: Math.round(performance.now()), level, msg: args.map(fmt).join(' ').slice(0, 2000) }); } catch {}
        return orig.apply(this, args);
      };
    }
    window.addEventListener('error', (e) => {
      window.__cap.push({ t: Math.round(performance.now()), level: 'uncaught', msg: String(e.message) + ' @ ' + e.filename + ':' + e.lineno });
    });
    window.addEventListener('unhandledrejection', (e) => {
      window.__cap.push({ t: Math.round(performance.now()), level: 'unhandledrejection', msg: fmt(e.reason) });
    });
  }
  if (!window.__viteWsCloses) {
    window.__viteWsCloses = [];
    const Native = window.WebSocket;
    function Patched(url, protocols) {
      const proto = Array.isArray(protocols) ? protocols.join(',') : String(protocols ?? '');
      if (proto.includes('vite-ping')) {
        const rec = { t: new Date().toISOString(), perf: Math.round(performance.now()), url: String(url), note: 'vite-hmr socket lost; ping blocked, reload suppressed' };
        window.__viteWsCloses.push(rec);
        console.warn('[mac-m2 test] vite-hmr websocket closed, reload suppressed: ' + JSON.stringify(rec));
        const fake = new EventTarget();
        fake.close = () => {};
        return fake; // never fires open or error: waitForSuccessfulPing never resolves
      }
      return protocols === undefined ? new Native(url) : new Native(url, protocols);
    }
    Patched.prototype = Native.prototype;
    Object.assign(Patched, { CONNECTING: 0, OPEN: 1, CLOSING: 2, CLOSED: 3 });
    window.WebSocket = Patched;
  }
  if (!window.__visChanges) {
    // Safari stops rAF (and so the engine) while its window is occluded: log every change.
    window.__visChanges = [{ t: Math.round(performance.now()), vis: document.visibilityState, note: 'at install' }];
    document.addEventListener('visibilitychange', () => {
      window.__visChanges.push({ t: Math.round(performance.now()), vis: document.visibilityState });
    });
  }
  return {
    visibility: document.visibilityState,
    capFrom: window.__capFrom,
    installedAtMs: window.__capInstalledAt,
    hyperionAtInstall: window.__capHyperionAtInstall,
    readyState: document.readyState,
    href: location.href,
    timeOrigin: performance.timeOrigin,
  };
}
